CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL, password_hash TEXT NOT NULL, role TEXT NOT NULL DEFAULT 'customer', wholesale_status TEXT NOT NULL DEFAULT 'none', business TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf TEXT NOT NULL, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS password_resets (token_hash TEXT PRIMARY KEY, user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS rate_buckets (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS products (id TEXT PRIMARY KEY, slug TEXT UNIQUE NOT NULL, sku TEXT UNIQUE NOT NULL, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL, brand TEXT NOT NULL DEFAULT '', size TEXT NOT NULL DEFAULT '', price BIGINT NOT NULL CHECK(price>=0), wholesale_price BIGINT CHECK(wholesale_price>=0), sale_price BIGINT, sale_start BIGINT, sale_end BIGINT, stock INTEGER NOT NULL DEFAULT 0 CHECK(stock>=0), low_stock INTEGER NOT NULL DEFAULT 5, wholesale_min INTEGER NOT NULL DEFAULT 6 CHECK(wholesale_min>=1), image TEXT NOT NULL DEFAULT '/placeholder.svg', gallery TEXT NOT NULL DEFAULT '[]', visible INTEGER NOT NULL DEFAULT 1, featured INTEGER NOT NULL DEFAULT 0, archived INTEGER NOT NULL DEFAULT 0, source_url TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS taxonomy (id TEXT PRIMARY KEY, kind TEXT NOT NULL, name TEXT NOT NULL, slug TEXT NOT NULL, image TEXT NOT NULL DEFAULT '/placeholder.svg', UNIQUE(kind,slug));
CREATE TABLE IF NOT EXISTS content (id TEXT PRIMARY KEY, data TEXT NOT NULL, updated_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS content_versions (id TEXT PRIMARY KEY, data TEXT NOT NULL, actor TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS zones (id TEXT PRIMARY KEY, lga TEXT NOT NULL, neighbourhood TEXT NOT NULL DEFAULT '', fee BIGINT NOT NULL DEFAULT 0 CHECK(fee>=0), minimum BIGINT NOT NULL DEFAULT 0 CHECK(minimum>=0), eta TEXT NOT NULL DEFAULT 'Delivery time confirmed after ordering', enabled INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS coupons (id TEXT PRIMARY KEY, code TEXT UNIQUE NOT NULL, type TEXT NOT NULL, value BIGINT NOT NULL CHECK(value>=0), minimum BIGINT NOT NULL DEFAULT 0, max_uses INTEGER NOT NULL DEFAULT 100, uses INTEGER NOT NULL DEFAULT 0, starts_at BIGINT, expires_at BIGINT, enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS orders (id TEXT PRIMARY KEY, ref TEXT UNIQUE NOT NULL, token_hash TEXT NOT NULL, user_id TEXT REFERENCES users(id), name TEXT NOT NULL, email TEXT NOT NULL, phone TEXT NOT NULL, address TEXT NOT NULL, zone TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', channel TEXT NOT NULL, pricing TEXT NOT NULL, subtotal BIGINT NOT NULL, discount BIGINT NOT NULL, delivery BIGINT NOT NULL, total BIGINT NOT NULL, coupon_id TEXT REFERENCES coupons(id), payment_status TEXT NOT NULL DEFAULT 'unpaid', status TEXT NOT NULL DEFAULT 'new', stock_state TEXT NOT NULL DEFAULT 'reserved', expires_at BIGINT NOT NULL, idempotency_key TEXT UNIQUE NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS order_items (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), product_id TEXT NOT NULL REFERENCES products(id), name TEXT NOT NULL, sku TEXT NOT NULL, size TEXT NOT NULL, qty INTEGER NOT NULL CHECK(qty>0), unit_price BIGINT NOT NULL, image TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_events (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), message TEXT NOT NULL, internal INTEGER NOT NULL DEFAULT 0, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS payments (reference TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), amount BIGINT NOT NULL, state TEXT NOT NULL DEFAULT 'pending', authorization_url TEXT NOT NULL DEFAULT '', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS refunds (id TEXT PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), amount BIGINT NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'recorded', created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS stock_movements (id TEXT PRIMARY KEY, product_id TEXT NOT NULL REFERENCES products(id), delta INTEGER NOT NULL, reason TEXT NOT NULL, actor TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_log (id TEXT PRIMARY KEY, actor TEXT NOT NULL, action TEXT NOT NULL, detail TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY, kind TEXT NOT NULL, message TEXT NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS email_outbox (id TEXT PRIMARY KEY, recipient TEXT NOT NULL, subject TEXT NOT NULL, body TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL DEFAULT 'pending', created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS orders_created ON orders(created_at);
CREATE INDEX IF NOT EXISTS orders_user ON orders(user_id);
CREATE INDEX IF NOT EXISTS products_category ON products(category);
CREATE INDEX IF NOT EXISTS events_order ON order_events(order_id);
